import{_ as e}from"./chunks/vip-crm.o9eihYVR.js";import{_ as l,o as r,c as i,a2 as t}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Πελάτες VIP και CRM","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/vip-crm.md","filePath":"el/plus/vip-crm.md"}'),o={name:"el/plus/vip-crm.md"};function s(p,a,c,h,n,m){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="πελατες-vip-και-crm" tabindex="-1">Πελάτες VIP και CRM <a class="header-anchor" href="#πελατες-vip-και-crm" aria-label="Permalink to &quot;Πελάτες VIP και CRM&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/vip-crm.png"><img src="'+e+'" alt="Πελάτες VIP και CRM: κενή λίστα προφίλ, δημιουργία προφίλ, φίλτρα και εταιρικές οντότητες τιμολόγησης. Δεν εμφανίζονται στοιχεία πελατών."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Πελάτες VIP και CRM: κενή λίστα προφίλ, δημιουργία προφίλ, φίλτρα και εταιρικές οντότητες τιμολόγησης. Δεν εμφανίζονται στοιχεία πελατών.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><p>Διατηρήστε εξουσιοδοτημένα προφίλ πελατών και το ιστορικό ρητά συνδεδεμένων κρατήσεων.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Στο VIP Clients &amp; CRM Profiles αναζητήστε όνομα, email ή τηλέφωνο. Ελέγξτε χειροκίνητα τις ενδείξεις διπλοεγγραφής· ίδιο email δεν προκαλεί αυτόματη συγχώνευση.</li><li>Ανοίξτε ή επεξεργαστείτε το σωστό προφίλ με δικαιώματα. Καταχωρίστε πραγματικά στοιχεία, γλώσσες και σχετικές προτιμήσεις· το email επιβάτη παραμένει προαιρετικό.</li><li>Ελέγξτε τις ρητά συνδεδεμένες κρατήσεις. Αν χρειάζεται, επιλέξτε μη συνδεδεμένη κράτηση της εταιρείας και συνδέστε την αφού επιβεβαιώσετε την ταυτότητα. Ελέγξτε αποθηκευμένες τοποθεσίες και συγκατάθεση.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Μην επινοείτε στοιχεία και μη συνδέετε κράτηση μόνο βάσει παρόμοιου ονόματος. Η εξαγωγή ή ανωνυμοποίηση απαιτεί εξουσιοδότηση και έλεγχο πολιτικής· όχι δοκιμές σε πραγματικούς πελάτες.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul>',16)])])}const f=l(o,[["render",s]]);export{_ as __pageData,f as default};
